-- Migration 0025 (was 0015 on merge/backend-into-cms-variants; additive, M7 demo purchases, decision D03a): an honestly named `sandbox` payment provider
-- that only ever runs in the `sandbox` environment, and orders.payment_mode='sandbox' for the orders it pays.
-- Generated by drizzle-kit (the four CHECK replacements below); these comments and the custom
-- payment_attempts_sandbox_guard trigger at the end were added by hand (Drizzle snapshots do not model triggers).
-- beta5 merge: the three payment CHECKs below are the union of this migration and beta's 0013 (manual,
-- O07) and 0021 (demo captures, Task 3.2), so existing manual and demo rows stay valid and both keep working.
-- payments_guard_attempt is beta's 0021 version (a demo attempt may end 'captured'); it is not touched here.
-- Unchanged on purpose: the demo/live rules of payments_guard_attempt (a `demo` attempt still needs a demo order), payments_guard_transaction (a fact must match its attempt's
-- provider/environment/merchant), the refund guards, orders.payment_mode immutability (commerce_guard_order) and
-- webhook_inbox (the sandbox adapter has no webhooks).
ALTER TABLE "orders" DROP CONSTRAINT "orders_statuses_valid";--> statement-breakpoint
ALTER TABLE "payment_attempts" DROP CONSTRAINT "payment_attempts_context_valid";--> statement-breakpoint
ALTER TABLE "payment_transactions" DROP CONSTRAINT "payment_transactions_fields_valid";--> statement-breakpoint
ALTER TABLE "refunds" DROP CONSTRAINT "refunds_fields_valid";--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_statuses_valid" CHECK ("orders"."order_status" IN ('pending_payment','confirmed','cancel_requested','cancelled','closed') AND "orders"."payment_status" IN ('unpaid','pending','authorized','paid','partially_refunded','refunded','failed') AND "orders"."fulfillment_status" IN ('unfulfilled','processing','partially_shipped','shipped','delivered','exception') AND "orders"."payment_mode" IN ('demo','live','sandbox','legacy_unknown'));--> statement-breakpoint
ALTER TABLE "payment_attempts" ADD CONSTRAINT "payment_attempts_context_valid" CHECK ((("payment_attempts"."provider"='demo' AND "payment_attempts"."environment"='demo') OR ("payment_attempts"."provider" IN ('kaspi','secondary') AND "payment_attempts"."environment" IN ('sandbox','live')) OR ("payment_attempts"."provider"='manual' AND "payment_attempts"."environment"='live' AND "payment_attempts"."merchant_account"='manual') OR ("payment_attempts"."provider"='sandbox' AND "payment_attempts"."environment"='sandbox')) AND length(btrim("payment_attempts"."merchant_account"))>0 AND length(btrim("payment_attempts"."merchant_reference"))>0 AND ("payment_attempts"."provider_session_id" IS NULL OR length(btrim("payment_attempts"."provider_session_id"))>0));--> statement-breakpoint
ALTER TABLE "payment_transactions" ADD CONSTRAINT "payment_transactions_fields_valid" CHECK ("payment_transactions"."currency"='KZT' AND "payment_transactions"."amount_minor">0 AND (("payment_transactions"."provider" IN ('kaspi','secondary') AND "payment_transactions"."environment" IN ('sandbox','live')) OR ("payment_transactions"."provider"='manual' AND "payment_transactions"."environment"='live' AND "payment_transactions"."merchant_account"='manual') OR ("payment_transactions"."provider"='demo' AND "payment_transactions"."environment"='demo' AND "payment_transactions"."merchant_account"='demo') OR ("payment_transactions"."provider"='sandbox' AND "payment_transactions"."environment"='sandbox')) AND "payment_transactions"."kind" IN ('authorization','capture','void') AND length(btrim("payment_transactions"."external_id"))>0 AND length(btrim("payment_transactions"."merchant_account"))>0 AND length(btrim("payment_transactions"."dedupe_key"))>0 AND jsonb_typeof("payment_transactions"."evidence")='object' AND "payment_transactions"."refund_epoch">=0);--> statement-breakpoint
ALTER TABLE "refunds" ADD CONSTRAINT "refunds_fields_valid" CHECK ("refunds"."currency"='KZT' AND "refunds"."amount_minor">0 AND "refunds"."version">0 AND (("refunds"."provider" IN ('kaspi','secondary') AND "refunds"."environment" IN ('sandbox','live')) OR ("refunds"."provider"='manual' AND "refunds"."environment"='live' AND "refunds"."merchant_account"='manual') OR ("refunds"."provider"='demo' AND "refunds"."environment"='demo' AND "refunds"."merchant_account"='demo') OR ("refunds"."provider"='sandbox' AND "refunds"."environment"='sandbox')) AND length(btrim("refunds"."merchant_account"))>0 AND ("refunds"."provider_refund_id" IS NULL OR length(btrim("refunds"."provider_refund_id"))>0) AND "refunds"."idempotency_key" ~ '^[ -~]{16,128}$' AND "refunds"."request_hash" ~ '^[0-9a-f]{64}$' AND "refunds"."status" IN ('reserved','pending','unknown','succeeded','failed','cancelled'));
--> statement-breakpoint
-- A sandbox attempt belongs to a sandbox order and a sandbox order takes only sandbox attempts, so sandbox
-- (demo) captures can never land on a live order, and live money can never land on a sandbox order.
CREATE FUNCTION payments_guard_sandbox_attempt() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_mode text;
BEGIN
  SELECT payment_mode INTO v_mode FROM orders WHERE id=NEW.order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown payment order' USING ERRCODE='23503'; END IF;
  IF (NEW.provider='sandbox')<>(v_mode='sandbox') THEN
    RAISE EXCEPTION 'Sandbox payment attempts belong to sandbox orders only' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER payment_attempts_sandbox_guard BEFORE INSERT OR UPDATE ON payment_attempts FOR EACH ROW EXECUTE FUNCTION payments_guard_sandbox_attempt();
